import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Architecture & User Space","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1795286990000}'),o={name:"guide/architecture.md"};function c(i,e,r,p,d,l){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-user-space" tabindex="-1">Architecture &amp; User Space <a class="header-anchor" href="#architecture-user-space" aria-label="Permalink to &quot;Architecture &amp; User Space&quot;">​</a></h1><p>JetPack separates untrusted browser code, security enforcement, and heavy native computation into three strictly isolated tiers.</p><h2 id="three-tier-system-architecture" tabindex="-1">Three-Tier System Architecture <a class="header-anchor" href="#three-tier-system-architecture" aria-label="Permalink to &quot;Three-Tier System Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| Tier 1: Browser / WASM Frontend                                             |</span></span>
<span class="line"><span>|   @jetpack/client (TypeScript) -&gt; jetpack-wasm (wasm32-unknown-unknown)     |</span></span>
<span class="line"><span>|   - Persistent Ed25519 / X25519 identity in localStorage                    |</span></span>
<span class="line"><span>|   - Out-of-Band pairing via jetpack://pair                                  |</span></span>
<span class="line"><span>|   - Encrypted binary WebSocket client (ws://127.0.0.1:9470)                 |</span></span>
<span class="line"><span>+--------------------------------------+--------------------------------------+</span></span>
<span class="line"><span>                                       |</span></span>
<span class="line"><span>                                       | 127.0.0.1:9470 (Origin + PNA + X25519</span></span>
<span class="line"><span>                                       | + ChaCha20-Poly1305 Binary Framing)</span></span>
<span class="line"><span>                                       v</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| Tier 2: Rust Tray Gatekeeper (jetpack-daemon)                               |</span></span>
<span class="line"><span>|   - Embedded Control Center HTTP server (http://127.0.0.1:9470)             |</span></span>
<span class="line"><span>|   - ChaCha20-Poly1305 encrypted paired client &amp; volume store (OS Vault key) |</span></span>
<span class="line"><span>|   - Ed25519 SignedAppCatalog verifier &amp; anti-spoofing enforcer              |</span></span>
<span class="line"><span>|   - Hardware Discovery (NVML / Vulkan / DX12 / Metal / sysctl)              |</span></span>
<span class="line"><span>|   - OCI CAS Manager (blobs/sha256/) + uv Python + RuntimeProvisioner        |</span></span>
<span class="line"><span>|   - In-Daemon Userspace Network Proxy (permissions.network_allowlist)       |</span></span>
<span class="line"><span>|   - Cross-platform OS Sandbox Runner + WorkerLifecycleManager               |</span></span>
<span class="line"><span>+--------------------------------------+--------------------------------------+</span></span>
<span class="line"><span>                                       |</span></span>
<span class="line"><span>                                       | Local Kernel IPC (UDS 0600 / Named Pipe</span></span>
<span class="line"><span>                                       | with AppContainer DACL) + [4B len] frames</span></span>
<span class="line"><span>                                       v</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| Tier 3: Sandboxed Native Workers                                            |</span></span>
<span class="line"><span>|   - Windows: AppContainer (Low Integrity SID) + NTFS ACLs + Job Object      |</span></span>
<span class="line"><span>|   - macOS:   Seatbelt (deny default) + gated AGXDeviceUserClient (Metal)    |</span></span>
<span class="line"><span>|   - Linux:   Bubblewrap (CLONE_NEWNET, pivot_root) + Landlock LSM           |</span></span>
<span class="line"><span>|   - Runtimes: standalone Python (uv), ffmpeg, llama.cpp, custom binaries    |</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span></code></pre></div><h3 id="tier-1-wasm-frontend-jetpack-wasm-jetpack-client" tabindex="-1">Tier 1: WASM Frontend (<code>jetpack-wasm</code> &amp; <code>@jetpack/client</code>) <a class="header-anchor" href="#tier-1-wasm-frontend-jetpack-wasm-jetpack-client" aria-label="Permalink to &quot;Tier 1: WASM Frontend (\`jetpack-wasm\` &amp; \`@jetpack/client\`)&quot;">​</a></h3><p>Web applications interact with JetPack through the high-level <code>@jetpack/client</code> TypeScript package (<code>JetPackAppClient</code>) layered on top of <code>jetpack-wasm</code>. All protocol framing, <code>Ed25519</code> request signing, <code>X25519</code> key exchange, and <code>ChaCha20-Poly1305</code> encryption execute inside WebAssembly (<code>jetpack-proto</code> compiled for <code>wasm32-unknown-unknown</code>) before bytes touch the browser <code>WebSocket</code>.</p><h3 id="tier-2-rust-tray-gatekeeper-jetpack-daemon" tabindex="-1">Tier 2: Rust Tray Gatekeeper (<code>jetpack-daemon</code>) <a class="header-anchor" href="#tier-2-rust-tray-gatekeeper-jetpack-daemon" aria-label="Permalink to &quot;Tier 2: Rust Tray Gatekeeper (\`jetpack-daemon\`)&quot;">​</a></h3><p><code>jetpack-daemon</code> is a lightweight native binary (<code>~5–10 MB</code>) managing the system tray icon (<code>tao</code> + <code>tray-icon</code>), the loopback HTTP/WebSocket server on <code>127.0.0.1:9470</code>, hardware discovery, OCI bundle caching (including slim single-example release seeding), isolated Python/native runtime provisioning, native OS dialogs (<code>rfd</code>), sanitized diagnostic bundle export/reporting (<code>diagnostics</code>), and worker lifecycle supervision.</p><p>No browser client ever communicates directly with a worker socket or pipe. <code>jetpack-daemon</code> decrypts incoming WebSocket frames, authorizes the session <code>Origin</code> against the target application, and forwards plaintext hybrid frames over local kernel IPC only to the authorized worker job.</p><h3 id="tier-3-sandboxed-native-workers" tabindex="-1">Tier 3: Sandboxed Native Workers <a class="header-anchor" href="#tier-3-sandboxed-native-workers" aria-label="Permalink to &quot;Tier 3: Sandboxed Native Workers&quot;">​</a></h3><p>Each launched job executes inside a dedicated per-job workspace (<code>&lt;root&gt;/workspaces/job_&lt;uuid&gt;</code>) under strict OS kernel confinement. Workers receive:</p><ul><li><code>JETPACK_IPC_ENDPOINT</code>: local Unix Domain Socket (<code>ipc.sock</code>) or Windows Named Pipe (<code>\\\\.\\pipe\\jetpack-worker-&lt;job_id&gt;</code>).</li><li><code>JETPACK_PROXY_ENDPOINT</code> / <code>HTTP_PROXY</code> / <code>ALL_PROXY</code>: userspace network proxy endpoint when <code>permissions.network_allowlist</code> is non-empty.</li><li><code>JETPACK_VOL_&lt;NAME&gt;</code>: sandbox-mounted paths for user-selected host folders declared in <code>[volumes.&lt;name&gt;]</code>.</li><li>Hermetic <code>PATH</code> prepended with <code>&lt;root&gt;/runtimes/&lt;name&gt;-&lt;version&gt;/bin</code> for declared <code>[runtimes]</code> dependencies.</li></ul><h2 id="user-space-directory-layout-jetpackpaths" tabindex="-1">User-Space Directory Layout (<code>JetPackPaths</code>) <a class="header-anchor" href="#user-space-directory-layout-jetpackpaths" aria-label="Permalink to &quot;User-Space Directory Layout (\`JetPackPaths\`)&quot;">​</a></h2><p>Implemented in <code>crates/jetpack-common/src/paths.rs</code>, JetPack keeps all configuration, caches, runtimes, and job workspaces strictly inside the unprivileged user&#39;s profile:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Default Root Path</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows (<code>windows/amd64</code>)</strong></td><td style="text-align:left;"><code>%APPDATA%\\JetPack</code></td></tr><tr><td style="text-align:left;"><strong>macOS (<code>darwin/arm64</code>)</strong></td><td style="text-align:left;"><code>~/Library/Application Support/JetPack</code></td></tr><tr><td style="text-align:left;"><strong>Linux (<code>linux/amd64</code>)</strong></td><td style="text-align:left;"><code>~/.config/jetpack</code></td></tr></tbody></table><p>You can override the root directory hermetically for testing or portable installations using the <code>JETPACK_HOME</code> environment variable (legacy <code>CORENODE_HOME</code> is also recognized as a fallback). On first startup, <code>JetPackPaths::init_dirs()</code> automatically migrates legacy <code>CoreNode</code> directories if present and enforces mode <code>0700</code> on Unix directories.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;JETPACK_ROOT&gt;/</span></span>
<span class="line"><span>├── config/</span></span>
<span class="line"><span>│   ├── daemon.toml              # Daemon bind address, port, logging, and [diagnostics] configuration</span></span>
<span class="line"><span>│   ├── paired_clients.db        # ChaCha20-Poly1305 AEAD encrypted SQLite DB (paired clients, authorized_volumes, settings)</span></span>
<span class="line"><span>│   └── pairing.ipc              # Local IPC socket/metadata for single-instance URI forwarding</span></span>
<span class="line"><span>├── logs/</span></span>
<span class="line"><span>│   ├── daemon.log               # Persistent UTF-8 tracing log (redacted in diagnostic exports)</span></span>
<span class="line"><span>│   └── jetpack-diagnostics-*.zip# Optional user-exported sanitized diagnostic bundles</span></span>
<span class="line"><span>├── blobs/</span></span>
<span class="line"><span>│   └── sha256/</span></span>
<span class="line"><span>│       ├── &lt;hex&gt;                # Content-Addressable OCI layer/config/manifest blobs</span></span>
<span class="line"><span>│       └── &lt;hex&gt;.unpacked/      # Tar-Slip-verified unpacked layer directories</span></span>
<span class="line"><span>├── runtimes/</span></span>
<span class="line"><span>│   ├── uv/                      # Portable uv binary</span></span>
<span class="line"><span>│   ├── python/                  # Managed python-build-standalone distributions</span></span>
<span class="line"><span>│   └── &lt;name&gt;-&lt;version&gt;/bin/    # Verified shared native runtimes (e.g., ffmpeg-9.0.2)</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   └── &lt;app-id&gt;/&lt;version&gt;/      # Deduplicated app bundles (hardlinks / APFS clones) + .venv</span></span>
<span class="line"><span>├── workspaces/</span></span>
<span class="line"><span>│   └── job_&lt;uuid&gt;/              # Ephemeral per-job sandbox RW directory + ipc.sock</span></span>
<span class="line"><span>└── cache/</span></span>
<span class="line"><span>    └── uv/                      # Shared zero-duplication wheel cache (UV_CACHE_DIR, mode 0700)</span></span></code></pre></div><h2 id="monorepo-crate-package-layout" tabindex="-1">Monorepo Crate &amp; Package Layout <a class="header-anchor" href="#monorepo-crate-package-layout" aria-label="Permalink to &quot;Monorepo Crate &amp; Package Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Path</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>crates/jetpack-proto</code></td><td style="text-align:left;"><code>wasm32</code>-compatible crate for <code>HybridFrame</code>, <code>X25519</code>/<code>Ed25519</code> handshake, <code>ChaCha20-Poly1305</code> cipher, pairing URIs, and <code>HardwareProfile</code> / control-plane schemas</td></tr><tr><td style="text-align:left;"><code>crates/jetpack-common</code></td><td style="text-align:left;"><code>AppManifest</code> (<code>app.toml</code>) strict parser/validator, <code>DaemonConfig</code>, <code>JetPackPaths</code>, and shared errors</td></tr><tr><td style="text-align:left;"><code>crates/jetpack-daemon</code></td><td style="text-align:left;">Tray agent, <code>127.0.0.1:9470</code> WS/Control Center server, ChaCha20-Poly1305 encrypted SQLite store (<code>rusqlite</code> <code>bundled</code>), pure-Rust TLS (<code>rustls-tls</code>), OCI/Python/runtime provisioners, OS sandboxes, and CLI tools</td></tr><tr><td style="text-align:left;"><code>crates/jetpack-wasm</code></td><td style="text-align:left;"><code>wasm-bindgen</code> browser SDK (<code>WasmClientIdentity</code>, <code>JetPackWasmClient</code>)</td></tr><tr><td style="text-align:left;"><code>web/</code></td><td style="text-align:left;">Embedded Control Center UI (<code>web/dist/</code>) and <code>@jetpack/client</code> TypeScript SDK (<code>web/packages/jetpack-client</code>)</td></tr><tr><td style="text-align:left;"><code>sdks/python/jetpack_sdk</code></td><td style="text-align:left;">Lightweight Python worker IPC library (<code>JetPackClient</code>, <code>HybridFrame</code>, zero-copy reader)</td></tr></tbody></table>`,19)])])}const g=a(o,[["render",c]]);export{u as __pageData,g as default};
